"use client";

import { Container } from "@/components/ui/container";
import Hotspot from "@/components/hotspot";
import { useRouter } from "next/navigation";

const HEADER_HEIGHT = 56;

export default function Home() {
  const router = useRouter();

  const handleConsoleActivate = () => {
    router.push("/puzzles/p5-final-console");
  };

  const handleDoorActivate = () => {
    router.push("/episodes");
  };

  return (
    <div className="relative min-h-screen">
      <div
        className="fixed inset-0 -z-10 bg-cover bg-center bg-no-repeat"
        style={{
          backgroundImage: "url(/assets/images/lab-bg.png)",
          backgroundAttachment: "fixed",
        }}
      >
        <div className="absolute inset-0 scene-overlay" />
        <div className="absolute inset-0 grid-background" />
      </div>

      <Container className="pt-8">
        <div
          className="relative w-full"
          style={{ height: `calc(100vh - ${HEADER_HEIGHT}px)` }}
        >
          <Hotspot
            id="console-hotspot"
            label="Console"
            x={30}
            y={60}
            onActivate={handleConsoleActivate}
          />
          <Hotspot
            id="door-hotspot"
            label="Door"
            x={75}
            y={55}
            onActivate={handleDoorActivate}
          />

          <div className="absolute bottom-8 left-1/2 -translate-x-1/2">
            <p className="text-sm text-muted-foreground bg-background/80 px-4 py-2 rounded-md backdrop-blur-sm">
              Tab to move, Enter to activate.
            </p>
          </div>
        </div>
      </Container>
    </div>
  );
}

