"use client";

import { useEffect, useState } from "react";
import { Container } from "@/components/ui/container";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { useProgress } from "@/store/progress";
import { allPuzzles, unmetDeps } from "@/lib/puzzles";
import { useRouter } from "next/navigation";

export default function EpisodesPage() {
  const [hydrated, setHydrated] = useState(false);
  const { solved } = useProgress();
  const router = useRouter();

  useEffect(() => {
    setHydrated(true);
  }, []);

  const getPuzzleStatus = (puzzleId: string) => {
    if (!hydrated) return "available";
    if (solved[puzzleId]) return "solved";
    const deps = unmetDeps(puzzleId, solved);
    if (deps.length > 0) return "locked";
    return "available";
  };

  return (
    <Container className="py-8">
      <div className="max-w-4xl mx-auto">
        <div className="mb-6">
          <h1 className="text-3xl font-bold bg-gradient-to-r from-glitch-primary via-glitch-secondary to-glitch-accent bg-clip-text text-transparent">
            All Episodes
          </h1>
          <p className="text-slate-300 mt-2">
            Complete puzzles to unlock new challenges and collect digits for the
            final console.
          </p>
        </div>

        <div className="grid gap-4">
          {allPuzzles.map((puzzle) => {
            const status = getPuzzleStatus(puzzle.id);
            const deps = unmetDeps(puzzle.id, solved);

            return (
              <Card
                key={puzzle.id}
                className={`bg-slate-900/80 border transition-all ${
                  status === "solved"
                    ? "border-glitch-primary/50"
                    : status === "locked"
                      ? "border-slate-700/50 opacity-60"
                      : "border-glitch-secondary/50 hover:border-glitch-secondary"
                }`}
              >
                <CardHeader>
                  <div className="flex items-start justify-between gap-4">
                    <div className="flex-1">
                      <CardTitle className="text-xl text-slate-100">
                        {puzzle.title}
                      </CardTitle>
                      <p className="text-sm text-slate-400 mt-1">
                        {puzzle.description}
                      </p>
                    </div>
                    <div className="flex flex-col items-end gap-2">
                      <Badge
                        variant={
                          status === "solved"
                            ? "default"
                            : status === "locked"
                              ? "secondary"
                              : "outline"
                        }
                        className={
                          status === "solved"
                            ? "bg-glitch-primary text-white"
                            : status === "locked"
                              ? "bg-slate-700 text-slate-400"
                              : "border-glitch-accent text-glitch-accent"
                        }
                      >
                        {status === "solved"
                          ? "✓ Solved"
                          : status === "locked"
                            ? "🔒 Locked"
                            : "Available"}
                      </Badge>
                      <span className="text-xs text-slate-500 capitalize">
                        {puzzle.kind}
                      </span>
                    </div>
                  </div>
                </CardHeader>
                <CardContent>
                  <div className="flex items-center justify-between">
                    <div className="text-sm text-slate-400">
                      {puzzle.grants?.digit && (
                        <span className="text-glitch-accent">
                          Grants Digit: {puzzle.grants.digit}
                        </span>
                      )}
                      {puzzle.grants?.token && (
                        <span className="text-glitch-secondary">
                          Grants Token: {puzzle.grants.token}
                        </span>
                      )}
                      {!puzzle.grants && (
                        <span className="text-slate-500">Final Challenge</span>
                      )}
                    </div>
                    <div className="flex gap-2">
                      {status === "locked" && deps.length > 0 && (
                        <span className="text-xs text-slate-500">
                          Requires: {deps.length} puzzle(s)
                        </span>
                      )}
                      <Button
                        size="sm"
                        onClick={() => router.push(`/puzzles/${puzzle.id}`)}
                        disabled={status === "locked"}
                        className={
                          status === "locked"
                            ? "opacity-50 cursor-not-allowed"
                            : "bg-glitch-primary hover:bg-glitch-primary/80"
                        }
                      >
                        {status === "solved" ? "Review" : "Start"}
                      </Button>
                    </div>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>

        <div className="mt-8 text-center">
          <Button
            onClick={() => router.push("/")}
            variant="outline"
            className="border-glitch-primary text-glitch-primary hover:bg-glitch-primary/10"
          >
            Back to Lab
          </Button>
        </div>
      </div>
    </Container>
  );
}

