src/store/progress.ts.content:
"use client";

import { create } from "zustand";

type Progress = {
  solved: Record<string, boolean>;
  digits: number[];
  tokens: Record<string, boolean>;
  startedAt?: number;
  finishedAt?: number;
  markSolved: (args: { id: string; digit?: number; token?: string }) => void;
  reset: () => void;
  startRun: () => void;
  finishRun: () => void;
};

const STORAGE_KEY = "glitch_progress_v1";

function load(): Omit<Progress, "markSolved" | "reset" | "startRun" | "finishRun"> {
  if (typeof window === "undefined") {
    return { solved: {}, digits: [], tokens: {}, startedAt: undefined, finishedAt: undefined };
  }
  try {
    const raw = localStorage.getItem(STORAGE_KEY);
    if (!raw) return { solved: {}, digits: [], tokens: {}, startedAt: undefined, finishedAt: undefined };
    const obj = JSON.parse(raw);
    return {
      solved: obj.solved ?? {},
      digits: obj.digits ?? [],
      tokens: obj.tokens ?? {},
      startedAt: obj.startedAt,
      finishedAt: obj.finishedAt,
    };
  } catch {
    return { solved: {}, digits: [], tokens: {}, startedAt: undefined, finishedAt: undefined };
  }
}

export const useProgress = create<Progress>((set, get) => ({
  ...load(),
  markSolved: ({ id, digit, token }) => {
    const next = { ...get().solved, [id]: true };
    const digits = [...get().digits];
    if (typeof digit === "number" && !digits.includes(digit)) {
      digits.push(digit);
    }
    const tokens = { ...get().tokens };
    if (token) tokens[token] = true;
    const snapshot = { 
      solved: next, 
      digits, 
      tokens,
      startedAt: get().startedAt,
      finishedAt: get().finishedAt,
    };
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(snapshot));
    }
    set(snapshot);
  },
  reset: () => {
    const snapshot = { 
      solved: {}, 
      digits: [], 
      tokens: {},
      startedAt: undefined,
      finishedAt: undefined,
    };
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(snapshot));
    }
    set(snapshot);
  },
  startRun: () => {
    if (get().startedAt) return;
    const snapshot = {
      ...get(),
      startedAt: Date.now(),
    };
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(snapshot));
    }
    set({ startedAt: snapshot.startedAt });
  },
  finishRun: () => {
    const snapshot = {
      ...get(),
      finishedAt: Date.now(),
    };
    if (typeof window !== "undefined") {
      localStorage.setItem(STORAGE_KEY, JSON.stringify(snapshot));
    }
    set({ finishedAt: snapshot.finishedAt });
  },
}));

