src/components/puzzle/P1ReinforcementMaz.content:
"use client";

import { useState, useEffect, useRef } from "react";
import mazeData from "./p1-maze.json";
import {
  type Maze,
  type NodeId,
  type Memory,
  atGoal,
  isDeadEndNode,
  shouldStop,
  nextChoice,
  updateMemory,
} from "./p1-rl";

const maze = mazeData as Maze;

const DECISION_PAUSE_MS = 600;
const MOVE_DURATION_MS = 800;

type Phase = "stopped" | "deciding" | "moving";

interface Props {
  onSolved: () => void;
}

export default function P1ReinforcementMaze({ onSolved }: Props) {
  const [current, setCurrent] = useState<NodeId>(maze.start);
  const [prev, setPrev] = useState<NodeId | undefined>(undefined);
  const [lastEdge, setLastEdge] = useState<string | null>(null);
  const [memory, setMemory] = useState<Memory>({});
  const [phase, setPhase] = useState<Phase>("stopped");
  const [status, setStatus] = useState<string>("Starting at Lab");
  const [nextNode, setNextNode] = useState<NodeId | null>(null);
  const solvedRef = useRef(false);

  useEffect(() => {
    if (atGoal(current, maze) && !solvedRef.current) {
      solvedRef.current = true;
      setStatus("Goal reached! You've arrived at the Bridge!");
      onSolved();
      return;
    }

    if (phase === "stopped") {
      // If this node is NOT a real stop, skip the pause and keep moving
      if (!shouldStop(current, prev, maze)) {
        setPhase("deciding");
        return;
      }
      const timer = setTimeout(() => {
        setPhase("deciding");
      }, DECISION_PAUSE_MS);
      return () => clearTimeout(timer);
    }

    if (phase === "deciding") {
      const { next, choiceEdge } = nextChoice(current, prev, maze, memory);
      setLastEdge(choiceEdge);
      setNextNode(next);
      setPhase("moving");
    }

    if (phase === "moving" && nextNode) {
      const timer = setTimeout(() => {
        setPrev(current);
        setCurrent(nextNode);
        setNextNode(null);

        if (isDeadEndNode(nextNode, maze)) {
          setStatus(`Dead end at ${nextNode}! Resetting to Lab...`);
          setTimeout(() => {
            setCurrent(maze.start);
            setPrev(undefined);
            setStatus("Reset to Lab. Making next decision...");
            setPhase("stopped");
          }, DECISION_PAUSE_MS);
        } else {
          if (shouldStop(nextNode, current, maze)) {
            setStatus(`Arrived at ${nextNode}. Use buttons below to label the last decision.`);
          }
          setPhase("stopped");
        }
      }, MOVE_DURATION_MS);
      return () => clearTimeout(timer);
    }
  }, [phase, current, prev, nextNode, memory, onSolved]);

  const handleFeedback = (label: "correct" | "incorrect") => {
    if (lastEdge) {
      setMemory(updateMemory(memory, lastEdge, label));
      setStatus(
        `Marked last decision as ${label}. Memory updated for edge: ${lastEdge}`
      );
    }
  };

  const currentNode = maze.nodes[current];
  const targetNode = nextNode && phase === "moving" ? maze.nodes[nextNode] : currentNode;

  const spriteX = targetNode.x;
  const spriteY = targetNode.y;

  return (
    <div className="space-y-4">
      <div className="relative w-full max-w-3xl mx-auto aspect-[1/1] overflow-hidden rounded-md border border-slate-700">
        <img
          src="/assets/images/maze/Ship_Maze.png?v=2"
          alt="Ship maze"
          className="absolute inset-0 h-full w-full object-contain select-none pointer-events-none"
        />

        <img
          src="/assets/images/maze/glitch.png"
          alt="Glitch character"
          className="absolute transition-all duration-[800ms] ease-in-out"
          style={{
            left: `${spriteX}%`,
            top: `${spriteY}%`,
            transform: "translate(-50%, -50%)",
            width: "3.75%",
            imageRendering: "pixelated",
            zIndex: 10,
          } as React.CSSProperties & { imageRendering: string }}
        />
      </div>

      <div
        className="p-4 bg-slate-800/50 rounded-lg border border-slate-700"
        role="status"
        aria-live="polite"
      >
        <p className="text-sm text-slate-300">{status}</p>
      </div>

      <div className="flex gap-3">
        <button
          onClick={() => handleFeedback("correct")}
          disabled={phase !== "stopped" || lastEdge === null || atGoal(current, maze)}
          className="flex-1 px-4 py-2 bg-green-600 hover:bg-green-700 disabled:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-green-500 focus:ring-offset-2 focus:ring-offset-slate-900"
        >
          Correct Decision
        </button>
        <button
          onClick={() => handleFeedback("incorrect")}
          disabled={phase !== "stopped" || lastEdge === null || atGoal(current, maze)}
          className="flex-1 px-4 py-2 bg-red-600 hover:bg-red-700 disabled:bg-slate-700 disabled:cursor-not-allowed disabled:opacity-50 text-white rounded-lg transition-colors focus:outline-none focus:ring-2 focus:ring-red-500 focus:ring-offset-2 focus:ring-offset-slate-900"
        >
          Incorrect Decision
        </button>
      </div>
    </div>
  );
}

