"use client";

import { useEffect, useState } from "react";
import { Container } from "@/components/ui/container";
import { Button } from "@/components/ui/button";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useProgress } from "@/store/progress";
import { byId } from "@/lib/puzzles";
import { useRouter } from "next/navigation";
import { AlertCircle } from "lucide-react";
import PuzzleHost from "@/components/puzzle/PuzzleHost";
import P1ReinforcementMaze from "@/components/puzzle/P1ReinforcementMaze";

export default function PuzzlePage({ params }: { params: { id: string } }) {
  const [hydrated, setHydrated] = useState(false);
  const { solved, finishRun } = useProgress();
  const router = useRouter();
  const puzzle = byId(params.id);

  useEffect(() => {
    setHydrated(true);
  }, []);

  if (!puzzle) {
    return (
      <Container className="py-8">
        <Alert className="max-w-2xl mx-auto bg-red-900/20 border-red-500">
          <AlertCircle className="h-4 w-4" />
          <AlertDescription>
            Puzzle not found. Please return to the episodes list.
          </AlertDescription>
        </Alert>
        <div className="text-center mt-4">
          <Button onClick={() => router.push("/episodes")}>
            Back to Episodes
          </Button>
        </div>
      </Container>
    );
  }

  return (
    <Container className="py-8">
      <div className="max-w-3xl mx-auto">
        <PuzzleHost
          id={puzzle.id}
          title={puzzle.title}
          description={puzzle.description}
          requires={puzzle.requires}
          grants={puzzle.grants}
        >
          {({ markSolved, solved: isSolved }) => (
              <>
                <div className="p-6 bg-slate-800/50 rounded-lg border border-slate-700">
                  <h3 className="text-lg font-semibold text-glitch-accent mb-3">
                    Puzzle Type: {puzzle.kind}
                  </h3>

                  {puzzle.kind === "maze" && (
                    <P1ReinforcementMaze onSolved={() => markSolved()} />
                  )}

                  {puzzle.kind === "multiselect" && (
                    <div className="space-y-2 text-slate-300">
                      <p>Select all reliable data sources from the list below.</p>
                      <p className="text-sm text-slate-400">
                        [Multiselect interface placeholder - to be implemented]
                      </p>
                    </div>
                  )}

                  {puzzle.kind === "text-entry" && (
                    <div className="space-y-2 text-slate-300">
                      <p>
                        Craft a precise prompt that meets the specified criteria.
                      </p>
                      <p className="text-sm text-slate-400">
                        [Text entry interface placeholder - to be implemented]
                      </p>
                    </div>
                  )}

                  {puzzle.kind === "slider" && (
                    <div className="space-y-2 text-slate-300">
                      <p>
                        Sort the statements by adjusting sliders to indicate fact
                        vs fiction.
                      </p>
                      <p className="text-sm text-slate-400">
                        [Slider interface placeholder - to be implemented]
                      </p>
                    </div>
                  )}

                  {puzzle.kind === "keypad" && (() => {
                    const coreSolved = hydrated && [
                      "p1-feedback-maze",
                      "p2-bad-data",
                      "p3-prompt-precision",
                      "p4-fact-fiction"
                    ].every((id) => solved[id]);

                    const keypadSrc = coreSolved
                      ? "/assets/images/keypad-colored.png"
                      : "/assets/images/keypad-plain.png";

                    return (
                      <div className="space-y-4 text-slate-300">
                        <p>Enter the correct digit sequence using the keypad below.</p>
                        <p className="text-sm text-slate-400">
                          Hint: Blue = N2, Red = N3, Orange = N1
                        </p>

                        <div className="relative w-full flex justify-center">
                          <img
                            src={keypadSrc}
                            alt={coreSolved ? "Keypad with color clues" : "Keypad without color clues"}
                            className="max-w-md w-full rounded-lg border border-slate-700"
                          />
                        </div>

                        <p className="text-sm text-slate-500 text-center">
                          {coreSolved
                            ? "All clues revealed—enter your final code!"
                            : "Solve all four core puzzles to reveal color clues."}
                        </p>
                      </div>
                    );
                  })()}
                </div>

                <div className="flex gap-3 pt-4">
                  {!isSolved && (
                    <Button
                      onClick={() => {
                        markSolved();
                        if (puzzle.id === "p5-final-console") {
                          finishRun();
                          router.push("/end");
                        }
                      }}
                      className="bg-glitch-primary hover:bg-glitch-primary/80"
                    >
                      Mark as Solved (Demo)
                    </Button>
                  )}
                  <Button
                    onClick={() => router.push("/episodes")}
                    variant="outline"
                    className="border-glitch-secondary text-glitch-secondary hover:bg-glitch-secondary/10"
                  >
                    Back to Episodes
                  </Button>
                </div>
              </>
            )}
        </PuzzleHost>

        <div className="mt-6 text-center">
          <Button
            onClick={() => router.push("/")}
            variant="ghost"
            className="text-slate-400 hover:text-slate-200"
            size="sm"
          >
            Return to Lab
          </Button>
        </div>
      </div>
    </Container>
  );
}

src/components/puzzle/PuzzleHost.tsx.content:
"use client";

import { ReactNode, useEffect, useState } from "react";
import { useProgress } from "@/store/progress";
import { unmetDeps } from "@/lib/puzzles";
import PuzzleHUD from "./PuzzleHUD";

type Grants = { digit?: number; token?: string };

export default function PuzzleHost(props: {
  id: string;
  title: string;
  description?: string;
  requires?: string[];
  grants?: Grants;
  children?: (ctx: { markSolved: () => void; solved: boolean }) => ReactNode;
}) {
  const { id, title, description, requires, grants, children } = props;
  const { solved, markSolved, startedAt, startRun } = useProgress();
  const [mounted, setMounted] = useState(false);

  const missing = unmetDeps(id, solved);
  const isLocked = missing.length > 0;
  const isSolved = mounted && !!solved[id];

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!startedAt) startRun();
  }, [startedAt, startRun]);

  useEffect(() => {
    console.info("puzzle_view", { id });
  }, [id]);

  if (isLocked) {
    return (
      <div className="rounded-lg border border-yellow-500/40 bg-yellow-900/10 p-4">
        <PuzzleHUD title={title} status="Locked" />
        <p className="mt-2 text-sm text-slate-300">
          This puzzle is locked. Required first: {missing.join(", ")}
        </p>
      </div>
    );
  }

  return (
    <div className="rounded-lg border border-white/10 bg-black/30 p-4">
      <PuzzleHUD
        title={title}
        status={isSolved ? "Solved" : "Available"}
      />
      {description && (
        <p className="text-sm text-slate-300 mb-3">{description}</p>
      )}
      {children?.({
        markSolved: () => {
          markSolved({ id, digit: grants?.digit, token: grants?.token });
          console.info("puzzle_solved", {
            id,
            digit: grants?.digit,
            token: grants?.token,
          });
        },
        solved: isSolved,
      })}
    </div>
  );
}

