"use client";

import * as React from "react";
import { cn } from "@/lib/utils";
import {
  Tooltip,
  TooltipContent,
  TooltipProvider,
  TooltipTrigger,
} from "@/components/ui/tooltip";

export interface HotspotProps {
  id: string;
  label: string;
  x: number;
  y: number;
  onActivate?: () => void;
}

const Hotspot: React.FC<HotspotProps> = ({ id, label, x, y, onActivate }) => {
  const handleKeyDown = (event: React.KeyboardEvent<HTMLDivElement>) => {
    if (event.key === "Enter" || event.key === " ") {
      event.preventDefault();
      onActivate?.();
    }
  };

  const handleClick = () => {
    onActivate?.();
  };

  return (
    <TooltipProvider>
      <Tooltip>
        <TooltipTrigger asChild>
          <div
            id={id}
            role="button"
            tabIndex={0}
            aria-label={label}
            className={cn(
              "absolute w-8 h-8 rounded-full",
              "bg-glitch-primary/60 border-2 border-glitch-primary",
              "cursor-pointer",
              "transition-all duration-200",
              "hover:scale-125 hover:bg-glitch-primary",
              "focus:outline-none focus:ring-4 focus:ring-glitch-accent focus:ring-offset-2",
              "focus:scale-125 focus:bg-glitch-primary",
              "drop-shadow-hotspot hover:drop-shadow-hotspot-focus focus:drop-shadow-hotspot-focus",
              "animate-pulse"
            )}
            style={{ left: `${x}%`, top: `${y}%` }}
            onClick={handleClick}
            onKeyDown={handleKeyDown}
          >
            <span className="sr-only">{label}</span>
          </div>
        </TooltipTrigger>
        <TooltipContent>
          <p>{label}</p>
        </TooltipContent>
      </Tooltip>
    </TooltipProvider>
  );
};

Hotspot.displayName = "Hotspot";

export default Hotspot;

