function formatTime(ms: number): string {
  const totalSeconds = Math.floor(ms / 1000);
  const mm = Math.floor(totalSeconds / 60);
  const ss = totalSeconds % 60;
  return `${mm.toString().padStart(2, "0")}:${ss.toString().padStart(2, "0")}`;
}

export default function EndPage() {
  const { finishedAt, startedAt, digits, reset } = useProgress();
  const router = useRouter();

  const totalTime =
    finishedAt && startedAt ? finishedAt - startedAt : 0;

  const handlePlayAgain = () => {
    if (
      confirm(
        "This will reset all your progress. Are you sure you want to play again?"
      )
    ) {
      reset();
      router.push("/start");
    }
  };

  return (
    <Container className="py-8">
      <div className="max-w-4xl mx-auto">
        <Card className="bg-slate-900/80 border-glitch-primary/30">
          <CardHeader className="text-center pb-4">
            <div className="flex justify-center mb-4">
              <div className="p-4 bg-glitch-primary/20 rounded-full">
                <Trophy className="h-16 w-16 text-glitch-primary" />
              </div>
            </div>
            <CardTitle className="text-4xl font-bold bg-gradient-to-r from-glitch-primary via-glitch-secondary to-glitch-accent bg-clip-text text-transparent">
              Challenge Complete!
            </CardTitle>
          </CardHeader>
          <CardContent className="space-y-6">
            <div className="text-center">
              <p className="text-lg text-slate-300 mb-6">
                Congratulations! You've successfully completed all the puzzles
                in Glitch Lab.
              </p>
            </div>

            <div className="grid md:grid-cols-2 gap-4">
              <Card className="bg-slate-800/50 border-slate-700">
                <CardContent className="p-6 text-center">
                  <div className="text-sm text-slate-400 mb-2">
                    Total Time
                  </div>
                  <div className="text-4xl font-bold font-mono text-glitch-primary">
                    {formatTime(totalTime)}
                  </div>
                </CardContent>
              </Card>

              <Card className="bg-slate-800/50 border-slate-700">
                <CardContent className="p-6 text-center">
                  <div className="text-sm text-slate-400 mb-2">
                    Digits Collected
                  </div>
                  <div className="text-4xl font-bold text-glitch-accent">
                    {digits.length}/3
                  </div>
                  <div className="mt-2 flex justify-center gap-2">
                    {digits.map((digit, idx) => (
                      <Badge
                        key={idx}
                        className="bg-glitch-accent text-slate-900"
                      >
                        {digit}
                      </Badge>
                    ))}
                  </div>
                </CardContent>
              </Card>
            </div>

            <div className="bg-glitch-primary/10 border border-glitch-primary/30 rounded-lg p-6">
              <div className="flex items-start gap-3">
                <CheckCircle2 className="h-6 w-6 text-glitch-primary flex-shrink-0 mt-1" />
                <div>
                  <h3 className="font-semibold text-glitch-primary mb-2">
                    All Puzzles Solved
                  </h3>
                  <ul className="space-y-1 text-sm text-slate-300">
                    <li>✓ Feedback Maze</li>
                    <li>✓ Bad Data</li>
                    <li>✓ Prompt Precision</li>
                    <li>✓ Fact or Fiction</li>
                    <li>✓ Final Console</li>
                  </ul>
                </div>
              </div>
            </div>

            <div className="flex flex-col sm:flex-row gap-3 pt-4">
              <Button
                onClick={handlePlayAgain}
                variant="outline"
                className="flex-1 border-glitch-secondary text-glitch-secondary hover:bg-glitch-secondary/10"
              >
